#pragma once
namespace orders {
inline void growth(crow::SimpleApp &app) {
    {Db d(path);d.exec("CREATE TABLE IF NOT EXISTS feedback(order_id TEXT PRIMARY KEY REFERENCES orders(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),comment TEXT NOT NULL,created INTEGER NOT NULL);");}
    CROW_ROUTE(app,"/api/orders/<string>/feedback").methods("POST"_method)([](const crow::request &r,std::string id){return handle([&]{
        auto o=office(r);auto j=body(r);auto rating=integer(j,"rating",1,5);auto comment=optionalText(j,"comment",1000);Db d(path);Transaction tx(d);
        Stmt s(d,"SELECT status FROM orders WHERE id=? AND office_id=?");s.bind(1,id).bind(2,o["office_id"].i());require(s.row()&&s.str(0)=="FULFILLED",409,"Feedback needs your fulfilled order");
        Stmt old(d,"SELECT rating,comment FROM feedback WHERE order_id=?");old.bind(1,id);if(old.row())require(old.num(0)==rating&&old.str(1)==comment,409,"Feedback already submitted");
        else {Stmt save(d,"INSERT INTO feedback VALUES(?,?,?,?)");save.bind(1,id).bind(2,rating).bind(3,comment).bind(4,now()).row();audit(d,"FEEDBACK_SUBMITTED",id,"office:"+std::to_string(o["office_id"].i()),"Rating "+std::to_string(rating));}tx.commit();Json out;out["saved"]=true;return json(200,std::move(out));
    });});
    CROW_ROUTE(app,"/api/accounts/<int>/remind").methods("POST"_method)([](const crow::request &r,int oid){return handle([&]{
        auto o=ownedOffice(r,oid);Db d(path);auto balance=outstanding(d,oid);require(balance>0,409,"No outstanding balance to remind");auto key=idem(r);Json message;message["stall_id"]=o["stall_id"].i();message["office_id"]=oid;message["body"]="Account reminder: outstanding fulfilled orders total INR "+std::to_string(balance/100)+"."+(balance%100<10?"0":"")+std::to_string(balance%100)+". View your account for current entries and payment details. This is not a new charge.";message["request_id"]="billing-"+key;
        auto result=http(env("CHAY_MERCHANT_URL","http://127.0.0.1:9181")+"/internal/billing-reminder","POST",message.dump(),{"X-Internal-Key: "+serviceKey()});require(result.status==200,static_cast<int>(result.status),"Reminder could not be stored; at most one per day is allowed");Json out;out["stored"]=true;return json(200,std::move(out));
    });});
    CROW_ROUTE(app,"/api/growth-report")([](const crow::request &r){return handle([&]{
        auto who=owner(r);auto sid=who["stall_id"].i();Db d(path);Json out;
        auto acquisition=merchant("/internal/acquisition",r);out["enquiries"]=Json(acquisition["enquiries"]);out["sources"]=Json::list();std::map<std::string,std::pair<long long,long long>> cohorts;std::map<std::string,long long> sourceRewards;
        for(auto &o:acquisition["offices"]){auto source=std::string(o["source"].s());Stmt earned(d,"SELECT COALESCE(SUM(amount),0) FROM referral_rewards WHERE stall_id=? AND referred=?");earned.bind(1,sid).bind(2,o["office_id"].i());earned.row();sourceRewards[source]+=earned.num(0);Stmt paid(d,"SELECT MIN(fulfilled_at),COUNT(*) FROM orders WHERE office_id=? AND stall_id=? AND status='FULFILLED' AND settlement='PAID' AND policy!='ADVANCE'");paid.bind(1,o["office_id"].i()).bind(2,sid);paid.row();auto &cohort=cohorts[source];if(paid.num(1)>0){cohort.first++;Stmt repeat(d,"SELECT COUNT(*) FROM orders WHERE office_id=? AND stall_id=? AND status='FULFILLED' AND settlement='PAID' AND policy!='ADVANCE' AND fulfilled_at<=?");repeat.bind(1,o["office_id"].i()).bind(2,sid).bind(3,paid.num(0)+30*86400);repeat.row();if(repeat.num(0)>1)cohort.second++;}}
        int sourceIndex=0;for(auto &[source,counts]:cohorts){out["sources"][sourceIndex]["source"]=source;out["sources"][sourceIndex]["paying_offices"]=counts.first;out["sources"][sourceIndex]["repeat_within_30_days"]=counts.second;Stmt spend(d,"SELECT COALESCE(SUM(amount),0) FROM business_expenses WHERE stall_id=? AND source=? AND kind='MARKETING'");spend.bind(1,sid).bind(2,source);spend.row();out["sources"][sourceIndex]["recorded_spend_paise"]=spend.num(0)+sourceRewards[source];if(counts.first>0)out["sources"][sourceIndex]["acquisition_cost_paise"]=((spend.num(0)+sourceRewards[source])/counts.first);else out["sources"][sourceIndex]["acquisition_cost_paise"]=Json();sourceIndex++;}
        Stmt totals(d,"SELECT COUNT(*),COALESCE(SUM(CASE WHEN status='FULFILLED' THEN total ELSE 0 END),0),COALESCE(SUM(status='CANCELLED'),0),COALESCE(SUM(settlement='REFUNDED'),0),COALESCE(SUM(status='FULFILLED' AND settlement='PAID'),0),COUNT(DISTINCT CASE WHEN status='FULFILLED' AND settlement='PAID' THEN office_id END) FROM orders WHERE stall_id=?");totals.bind(1,sid);totals.row();out["orders"]=totals.num(0);out["fulfilled_sales_paise"]=totals.num(1);out["cancelled_orders"]=totals.num(2);out["refunded_orders"]=totals.num(3);out["paid_fulfilled_orders"]=totals.num(4);out["paying_offices"]=totals.num(5);
        Stmt costs(d,"SELECT COUNT(*),COALESCE(SUM(i.cost_paise<0),0),COALESCE(SUM(CASE WHEN i.cost_paise>=0 THEN i.cost_paise*i.quantity ELSE 0 END),0),COALESCE(SUM(CASE WHEN i.list_price>i.price THEN (i.list_price-i.price)*i.quantity ELSE 0 END),0) FROM order_items i JOIN orders o ON o.id=i.order_id WHERE o.stall_id=? AND o.status='FULFILLED'");costs.bind(1,sid);costs.row();
        Stmt expenses(d,"SELECT COALESCE(SUM(CASE WHEN kind='MARKETING' THEN amount ELSE 0 END),0),COALESCE(SUM(CASE WHEN kind='PROCESSING' THEN amount ELSE 0 END),0) FROM business_expenses WHERE stall_id=?");expenses.bind(1,sid);expenses.row();Stmt rewards(d,"SELECT COALESCE(SUM(amount),0) FROM referral_rewards WHERE stall_id=?");rewards.bind(1,sid);rewards.row();Stmt refunds(d,"SELECT COALESCE(SUM(total),0) FROM orders WHERE stall_id=? AND settlement='REFUNDED'");refunds.bind(1,sid);refunds.row();
        out["refunded_paise"]=refunds.num(0);out["fulfilled_discounts_paise"]=costs.num(3);out["recorded_marketing_paise"]=expenses.num(0);out["recorded_processing_paise"]=expenses.num(1);out["referral_rewards_paise"]=rewards.num(0);bool complete=costs.num(0)>0&&costs.num(1)==0;out["contribution_available"]=complete;out["contribution_note"]="Estimate from fulfilled net sales, snapshotted supplied unit costs and recorded fees/marketing/rewards. Excludes unrecorded costs and taxes. Discounts already reduce sales; cancelled refunded orders are excluded from fulfilled sales.";
        if(complete)out["contribution_estimate_paise"]=totals.num(1)-costs.num(2)-expenses.num(0)-expenses.num(1)-rewards.num(0);else out["contribution_estimate_paise"]=Json();
        Stmt repeat(d,"SELECT COUNT(*) FROM (SELECT office_id FROM orders WHERE stall_id=? AND status='FULFILLED' GROUP BY office_id HAVING COUNT(*)>1)");repeat.bind(1,sid);repeat.row();out["repeat_offices"]=repeat.num(0);
        out["feedback"]=Json::list();int i=0;Stmt f(d,"SELECT o.office_name,f.order_id,f.rating,f.comment FROM feedback f JOIN orders o ON o.id=f.order_id WHERE o.stall_id=? ORDER BY f.created DESC LIMIT 100");f.bind(1,sid);while(f.row()){out["feedback"][i]["office_name"]=f.str(0);out["feedback"][i]["order_id"]=f.str(1);out["feedback"][i]["rating"]=f.num(2);out["feedback"][i++]["comment"]=f.str(3);}out["profit_available"]=false;return json(200,std::move(out));
    });});
}
}
